
-- Made in VS Code on 2026-11-17 with all-MiniLM-L6-v2 (384 dimensions).
-- Safe to run again: existing titles are updated, not duplicated.

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS searches (
    id     integer PRIMARY KEY,
    search  text    NOT NULL,
    embedding    vector(384)
);

ON CONFLICT (id) DO UPDATE SET
    search = EXCLUDED.search, 
    embedding = EXCLUDED.embedding;

-- Vector index for cosine distance (the <=> operator).
CREATE INDEX IF NOT EXISTS search_embedding_idx ON searches USING hnsw (embedding vector_cosine_ops);

-- Self-check. Expect: embedding = with_vectors, and dimensions = 384.
SELECT count(*) AS searches, count(embedding) AS with_vectors, max(vector_dims(embedding)) AS dimensions
FROM searches;
